import puppeteer from 'puppeteer-core';
import fs from 'node:fs';
import path from 'node:path';

const chromeCandidates=[process.env.CHROME_PATH,process.platform==='win32'?'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe':null,'/usr/bin/google-chrome','/usr/bin/google-chrome-stable','/usr/bin/chromium','/usr/bin/chromium-browser'].filter(Boolean);
const chrome=chromeCandidates.find(candidate=>fs.existsSync(candidate));
if(!chrome)throw new Error('Chrome/Chromium not found. Set CHROME_PATH to run the browser tests.');
const root=path.resolve('dist');
const fileUrl=`file:///${path.join(root,'PixelQuota.html').replace(/\\/g,'/')}`;
const artifacts=path.resolve('tests','artifacts');
const downloads=path.resolve('tests','downloads');
fs.mkdirSync(artifacts,{recursive:true});fs.mkdirSync(downloads,{recursive:true});
for(const f of fs.readdirSync(downloads))fs.rmSync(path.join(downloads,f),{force:true,recursive:true});

const browser=await puppeteer.launch({headless:true,executablePath:chrome,args:['--no-sandbox','--allow-file-access-from-files']});
const page=await browser.newPage();
const errors=[];
page.on('pageerror',e=>errors.push(`page:${e.message}`));
page.on('console',m=>{if(m.type()==='error')errors.push(`console:${m.text()}`)});
const client=await page.createCDPSession();
await client.send('Page.setDownloadBehavior',{behavior:'allow',downloadPath:downloads});
await page.setViewport({width:1440,height:1050,deviceScaleFactor:1});
await page.goto(fileUrl,{waitUntil:'load'});
await page.waitForFunction(()=>!!window.PixelQuotaTest);
const pageMetaDefault=await page.evaluate(()=>({title:document.title,description:document.querySelector('meta[name="description"]')?.content||'',ogTitle:document.querySelector('meta[property="og:title"]')?.content||''}));
if(!pageMetaDefault.title.startsWith('PixelQuota')||pageMetaDefault.title.includes('Exact KB')||pageMetaDefault.description.length<30||pageMetaDefault.ogTitle!==pageMetaDefault.title)throw new Error(`multi-tool page metadata failed ${JSON.stringify(pageMetaDefault)}`);

async function setLocale(locale){
  const current=await page.evaluate(()=>document.documentElement.lang);
  if(current===locale)return;
  await page.click('#languageToggle');
  await page.click(`#languageOptions [data-locale="${locale}"]`);
  await page.waitForFunction(expected=>document.documentElement.lang===expected,{},locale);
}

if(await page.$('#cameraBtn')||await page.$('#cameraInput'))throw new Error('camera controls still exist');

await setLocale('zh-TW');
const zh=await page.evaluate(()=>({hero:document.querySelector('#heroTitle').textContent,drop:document.querySelector('.drop-zone strong').textContent,guide:document.querySelector('[data-i18n="guideLabel"]').textContent,privacy:document.querySelector('footer [data-i18n="privacyLink"]').textContent,placeholder:document.querySelector('#maxWidth').placeholder}));
if(!zh.hero.includes('精準 KB')||!zh.drop.includes('圖片')||!zh.guide.includes('使用說明')||zh.privacy!=='隱私說明'||zh.placeholder!=='不限')throw new Error(`zh translation incomplete ${JSON.stringify(zh)}`);
const zhPageTitle=await page.title();if(zhPageTitle!=='PixelQuota - 本機隱私圖片工具，不上傳')throw new Error(`localized multi-tool title failed: ${zhPageTitle}`);
const customLanguage=await page.evaluate(()=>({nativeSelect:!!document.querySelector('.header-tools select'),value:document.querySelector('#languageValue').textContent,selected:document.querySelector('#languageOptions [aria-selected="true"]')?.dataset.locale||'',toggleAppearance:getComputedStyle(document.querySelector('#languageToggle')).appearance}));
if(customLanguage.nativeSelect||customLanguage.value!=='繁中'||customLanguage.selected!=='zh-TW'||customLanguage.toggleAppearance==='auto')throw new Error(`custom language control failed ${JSON.stringify(customLanguage)}`);
const languageMenuLabels=await page.evaluate(()=>[...document.querySelectorAll('#languageOptions [data-locale]')].map(button=>({locale:button.dataset.locale,text:button.textContent.trim(),children:button.children.length})));
const expectedLanguageLabels=[['en','English'],['zh-TW','繁體中文'],['zh-CN','简体中文'],['ja','日本語'],['ko','한국어']];
if(JSON.stringify(languageMenuLabels.map(x=>[x.locale,x.text]))!==JSON.stringify(expectedLanguageLabels)||languageMenuLabels.some(x=>x.children))throw new Error(`language menu labels duplicated or incomplete ${JSON.stringify(languageMenuLabels)}`);
const localeCompact={en:'EN','zh-TW':'繁中','zh-CN':'简中',ja:'日本語',ko:'한국어'},localeSmoke={};
for(const locale of Object.keys(localeCompact)){
  await setLocale(locale);
  localeSmoke[locale]=await page.evaluate(()=>({lang:document.documentElement.lang,compact:document.querySelector('#languageValue').textContent,hero:document.querySelector('#heroTitle').textContent,process:document.querySelector('#processBtn b').textContent,inspect:document.querySelector('#backgroundInspectBtn').textContent.trim(),inspectTitle:document.querySelector('#backgroundInspectTitle').textContent.trim()}));
  if(localeSmoke[locale].lang!==locale||localeSmoke[locale].compact!==localeCompact[locale]||!localeSmoke[locale].hero.trim()||!localeSmoke[locale].process.trim()||!localeSmoke[locale].inspect||!localeSmoke[locale].inspectTitle)throw new Error(`locale smoke failed ${locale} ${JSON.stringify(localeSmoke[locale])}`);
  if(locale==='en'&&/[\u3400-\u9fff]/.test(localeSmoke[locale].inspect+localeSmoke[locale].inspectTitle))throw new Error(`release inspector leaked Chinese into English ${JSON.stringify(localeSmoke[locale])}`);
}
